.version 8.0
.target sm_89
.address_size 64

.visible .entry conv2d_nchw_f32(
    .param .u64 x_ptr,
    .param .u64 w_ptr,
    .param .u64 b_ptr,
    .param .u64 y_ptr,
    .param .u32 N,
    .param .u32 C_in,
    .param .u32 H_in,
    .param .u32 W_in,
    .param .u32 C_out,
    .param .u32 K_h,
    .param .u32 K_w,
    .param .u32 stride_h,
    .param .u32 stride_w,
    .param .u32 pad_h,
    .param .u32 pad_w,
    .param .u32 dil_h,
    .param .u32 dil_w,
    .param .u32 H_out,
    .param .u32 W_out,
    .param .u32 has_bias,
    .param .u32 total_elems
)
{
    .reg .pred   %p<16>;
    .reg .b32    %r<80>;
    .reg .b64    %rd<40>;
    .reg .f32    %f<10>;

    // Load kernel arguments
    ld.param.u64 %rd1,  [x_ptr];
    ld.param.u64 %rd2,  [w_ptr];
    ld.param.u64 %rd3,  [b_ptr];
    ld.param.u64 %rd4,  [y_ptr];

    ld.param.u32 %r10, [N];
    ld.param.u32 %r11, [C_in];
    ld.param.u32 %r12, [H_in];
    ld.param.u32 %r13, [W_in];
    ld.param.u32 %r14, [C_out];
    ld.param.u32 %r15, [K_h];
    ld.param.u32 %r16, [K_w];
    ld.param.u32 %r17, [stride_h];
    ld.param.u32 %r18, [stride_w];
    ld.param.u32 %r19, [pad_h];
    ld.param.u32 %r20, [pad_w];
    ld.param.u32 %r21, [dil_h];
    ld.param.u32 %r22, [dil_w];
    ld.param.u32 %r23, [H_out];
    ld.param.u32 %r24, [W_out];
    ld.param.u32 %r25, [has_bias];
    ld.param.u32 %r26, [total_elems];

    // Compute linear thread id: tid = threadIdx.x + blockIdx.x * blockDim.x
    mov.u32 %r30, %tid.x;
    mov.u32 %r31, %ntid.x;
    mov.u32 %r32, %ctaid.x;
    mul.lo.u32 %r33, %r31, %r32;
    add.u32 %r34, %r30, %r33; // r34 = tid

    // if tid >= total_elems: return
    setp.ge.u32 %p0, %r34, %r26;
    @%p0 bra RET;

    // Decode indices from tid into (n, oc, oy, ox)
    // ox = tid % W_out
    rem.u32 %r40, %r34, %r24;
    // t = tid / W_out
    div.u32 %r41, %r34, %r24;

    // oy = t % H_out
    rem.u32 %r42, %r41, %r23;
    // t = t / H_out
    div.u32 %r43, %r41, %r23;

    // oc = t % C_out
    rem.u32 %r44, %r43, %r14;
    // n = t / C_out
    div.u32 %r45, %r43, %r14;

    // Compute input origin coordinates (signed)
    // in_y_origin = oy * stride_h - pad_h
    mul.lo.u32 %r50, %r42, %r17;
    sub.s32 %r51, %r50, %r19; // signed sub

    // in_x_origin = ox * stride_w - pad_w
    mul.lo.u32 %r52, %r40, %r18;
    sub.s32 %r53, %r52, %r20; // signed sub

    // Load bias or set zero
    mov.f32 %f0, 0f00000000; // 0.0
    setp.ne.u32 %p1, %r25, 0;
    @!%p1 bra BIAS_DONE;
        // load bias[oc]
        mul.wide.u32 %rd10, %r44, 4;
        add.s64 %rd11, %rd3, %rd10;
        ld.global.f32 %f0, [%rd11];
BIAS_DONE:

    // acc = bias (or 0)
    mov.f32 %f1, %f0;

    // Prepare constants
    // We'll use r10..r24 for dims as loaded.

    // c loop: for (c = 0; c < C_in; ++c)
    mov.u32 %r60, 0;        // c = 0
C_LOOP:
    setp.ge.u32 %p2, %r60, %r11;
    @%p2 bra C_LOOP_END;

    // ky loop: for (ky = 0; ky < K_h; ++ky)
    mov.u32 %r61, 0;        // ky = 0
KY_LOOP:
    setp.ge.u32 %p3, %r61, %r15;
    @%p3 bra KY_LOOP_END;

        // yi = in_y_origin + ky * dil_h
        mul.lo.u32 %r62, %r61, %r21;
        add.s32 %r63, %r51, %r62; // yi (signed)

        // if (yi < 0 || yi >= H_in) continue;
        setp.lt.s32 %p4, %r63, 0;
        setp.ge.s32 %p5, %r63, %r12;
        or.pred %p6, %p4, %p5;
        @%p6 bra KY_CONT;

        // kx loop: for (kx = 0; kx < K_w; ++kx)
        mov.u32 %r64, 0;    // kx = 0
KX_LOOP:
        setp.ge.u32 %p7, %r64, %r16;
        @%p7 bra KX_LOOP_END;

            // xi = in_x_origin + kx * dil_w
            mul.lo.u32 %r65, %r64, %r22;
            add.s32 %r66, %r53, %r65; // xi (signed)

            // if (xi < 0 || xi >= W_in) continue;
            setp.lt.s32 %p8, %r66, 0;
            setp.ge.s32 %p9, %r66, %r13;
            or.pred %p10, %p8, %p9;
            @%p10 bra KX_CONT;

            // Compute input offset: (((n*C_in + c)*H_in + yi)*W_in + xi)
            mul.lo.u32 %r70, %r45, %r11;        // n*C_in
            add.u32    %r71, %r70, %r60;        // + c
            mul.lo.u32 %r72, %r71, %r12;        // * H_in
            add.s32    %r73, %r72, %r63;        // + yi
            mul.lo.u32 %r74, %r73, %r13;        // * W_in
            add.s32    %r75, %r74, %r66;        // + xi

            // Compute weight offset: (((oc*C_in + c)*K_h + ky)*K_w + kx)
            mul.lo.u32 %r76, %r44, %r11;        // oc*C_in
            add.u32    %r77, %r76, %r60;        // + c
            mul.lo.u32 %r78, %r77, %r15;        // * K_h
            add.u32    %r79, %r78, %r61;        // + ky
            mul.lo.u32 %r0,  %r79, %r16;        // * K_w
            add.u32    %r1,  %r0,  %r64;        // + kx

            // Load input and weight
            mul.wide.u32 %rd20, %r75, 4;
            add.s64 %rd21, %rd1, %rd20;
            ld.global.f32 %f2, [%rd21];

            mul.wide.u32 %rd22, %r1, 4;
            add.s64 %rd23, %rd2, %rd22;
            ld.global.f32 %f3, [%rd23];

            // acc = fma(in, w, acc)
            fma.rn.f32 %f1, %f2, %f3, %f1;

KX_CONT:
            add.u32 %r64, %r64, 1;
            bra KX_LOOP;
KX_LOOP_END:

KY_CONT:
        add.u32 %r61, %r61, 1;
        bra KY_LOOP;
KY_LOOP_END:

    add.u32 %r60, %r60, 1;
    bra C_LOOP;
C_LOOP_END:

    // Store result to y at index ((((n*C_out + oc)*H_out + oy)*W_out + ox))
    mul.lo.u32 %r2, %r45, %r14;      // n*C_out
    add.u32    %r3, %r2,  %r44;      // + oc
    mul.lo.u32 %r4, %r3,  %r23;      // * H_out
    add.u32    %r5, %r4,  %r42;      // + oy
    mul.lo.u32 %r6, %r5,  %r24;      // * W_out
    add.u32    %r7, %r6,  %r40;      // + ox

    mul.wide.u32 %rd30, %r7, 4;
    add.s64 %rd31, %rd4, %rd30;
    st.global.f32 [%rd31], %f1;

RET:
    ret;
}
