        assert x.is_cuda, "Input must be on CUDA device"
        device = x.device
        dtype = x.dtype
        assert dtype == torch.float32, "This kernel supports only float32"

        # Extract parameters
        N, C_in, H_in, W_in = x.shape
        k = self.conv2d.kernel_size
        K_h = k[0] if isinstance(k, tuple) else int(k)
        K_w = k[1] if isinstance(k, tuple) else int(k)
        s = self.conv2d.stride
        stride_h = s[0] if isinstance(s, tuple) else int(s)
        stride_w = s[1] if isinstance(s, tuple) else int(s)
        p = self.conv2d.padding
        pad_h = p[0] if isinstance(p, tuple) else int(p)
        pad_w = p[1] if isinstance(p, tuple) else int(p)
        d = self.conv2d.dilation
        dil_h = d[0] if isinstance(d, tuple) else int(d)
        dil_w = d[1] if isinstance(d, tuple) else int(d)
        C_out = self.conv2d.out_channels

