        block_x = 256
        grid_x = (total + block_x - 1) // block_x

        module.launch(
            "conv2d_nchw_f32",
            grid=(grid_x, 1, 1),
            block=(block_x, 1, 1),
            arguments=[
                x, w, b, y,
                u32(N), u32(C_in), u32(H_in), u32(W_in),
                u32(C_out), u32(K_h), u32(K_w),
                u32(stride_h), u32(stride_w),
                u32(pad_h), u32(pad_w),
                u32(dil_h), u32(dil_w),
                u32(H_out), u32(W_out),
                u32(has_bias),
                u32(total),
            ],
            shared_memory=0,
            stream=torch.cuda.current_stream(device),
        )
